package com.careflow.hospital.reservations;
import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface SlotReservationRepository extends JpaRepository<SlotReservation,UUID>{@Modifying@Query("update SlotReservation r set r.status='EXPIRED' where r.status='ACTIVE' and r.expiresAt<=:now")int expireBefore(@Param("now")Instant now);@Query("select r from SlotReservation r where r.doctorId=:doctorId and r.status='ACTIVE' and r.expiresAt>:now and r.startsAt<:end and r.endsAt>:start")List<SlotReservation> findActiveOverlaps(@Param("doctorId")UUID doctorId,@Param("start")Instant start,@Param("end")Instant end,@Param("now")Instant now);List<SlotReservation> findAllByPatientIdOrderByCreatedAtDesc(UUID patientId);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)@Query("select r from SlotReservation r where r.id=:id")Optional<SlotReservation> findByIdForUpdate(@Param("id")UUID id);}
